import { useEffect, useState } from "react";
import { Pie, Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
  CategoryScale,
  LinearScale,
  BarElement,
} from "chart.js";

ChartJS.register(
  ArcElement,
  Tooltip,
  Legend,
  CategoryScale,
  LinearScale,
  BarElement
);

export default function Reports() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/orders/")
      .then(res => res.json())
      .then(setOrders)
      .catch(err => console.error("Failed to fetch orders", err));
  }, []);

  /* ---------------- Revenue ---------------- */
  const revenue = orders.reduce((sum, o) => sum + (Number(o.total) || 0), 0);

  /* ---------------- Pie chart (status) ---------------- */
  const statusCounts = orders.reduce((acc, o) => {
    const s = o.status || "Pending";
    acc[s] = (acc[s] || 0) + 1;
    return acc;
  }, {});

  const pieData = {
    labels: Object.keys(statusCounts),
    datasets: [
      {
        data: Object.values(statusCounts),
        backgroundColor: ["#facc15", "#22c55e", "#3b82f6"],
      },
    ],
  };

  /* ---------------- Bar chart (daily sales) ---------------- */
  const dailySales = {};

  orders.forEach(o => {
    if (!o.created_at) return;
    const date = o.created_at.split("T")[0];
    dailySales[date] = (dailySales[date] || 0) + (Number(o.total) || 0);
  });

  const barData = {
    labels: Object.keys(dailySales),
    datasets: [
      {
        label: "Daily Revenue",
        data: Object.values(dailySales),
        backgroundColor: "#6366f1",
      },
    ],
  };

  return (
    <div style={{ padding: 20 }}>
      <h3>Sales Report</h3>

      <h2>Total Revenue: ₹{revenue.toFixed(2)}</h2>

      <div style={{ display: "flex", gap: 40, marginTop: 30, flexWrap: "wrap" }}>
        <div style={{ width: 350 }}>
          <h4>Orders by Status</h4>
          <Pie data={pieData} />
        </div>

        <div style={{ width: 500 }}>
          <h4>Daily Sales</h4>
          <Bar data={barData} />
        </div>
      </div>
    </div>
  );
}
